fn set_every_word(s:&mut Vdi3805Snapshot,v:f64){
 for p in &mut s.catalog.products{match &mut p.configuration.attributes{crate::SheetAttributes::ValveHeating(a)=>{a.kvs_m3_s=v;a.authority_min=v;a.authority_max=v;},crate::SheetAttributes::Radiator(a)=>{a.standard_output_w=v;a.heat_exponent_n=v;a.length_m=v;a.height_m=v;a.depth_m=v;},crate::SheetAttributes::PumpHeating(a)=>{a.nominal_flow_m3_s=v;a.nominal_head_m=v;a.motor_power_w=v;a.hydraulic_efficiency=v;},crate::SheetAttributes::HeatGenerator(a)=>{a.nominal_heat_output_w=v;a.flow_temp_max_c=v;a.return_temp_min_c=v;},crate::SheetAttributes::Generic(_)=>{}}}
 for g in s.geometry.values_mut(){g.bbox.min_x=v;g.bbox.min_y=v;g.bbox.min_z=v;g.bbox.max_x=v;g.bbox.max_y=v;g.bbox.max_z=v;for c in &mut g.connections{c.position=[v;3];c.direction=[v;3];if let Some(value)=&mut c.diameter_mm{*value=v;}}for value in g.parameters.values_mut(){*value=v;}}
 for c in s.curves.values_mut(){c.x_unit.si_factor=v;c.y_unit.si_factor=v;for p in &mut c.points{p.x=v;p.y=v;}}
}
