fn sqlite_snapshot_vdi3805_shared_independent_sql_corpus_refuses_lost_native_ownership(){
 use std::{io::Write,process::{Command,Stdio}};
 let cases=include_str!("../../🧫️fixtures/🪶️sqlite/⚠️malformed.json");let edits:Vec<String>=serde_json::from_str(cases).unwrap();let bytes=export_sqlite_database(&database(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
 let script="import{Database}from'bun:sqlite';const bytes=new Uint8Array(await Bun.stdin.arrayBuffer());for(const sql of JSON.parse(process.argv.at(-1))){const db=Database.deserialize(bytes);try{db.run('PRAGMA foreign_keys=OFF');db.run('PRAGMA ignore_check_constraints=ON');db.exec(sql);const out=db.serialize(),header=new Uint8Array(4);new DataView(header.buffer).setUint32(0,out.length,true);await Bun.write(Bun.stdout,header);await Bun.write(Bun.stdout,out)}finally{db.close()}}";
 let mut child=Command::new("bun").args(["-e",script,"--",cases]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let mut position=0;
 for sql in edits{let end=position+4;let length=u32::from_le_bytes(output.stdout[position..end].try_into().unwrap())as usize;position=end;let end=position+length;let refused=match import_sqlite_database(&output.stdout[position..end],SqliteDatabaseLimits::default(),&mut |_|true){Ok(database)=>Vdi3805Snapshot::from_sqlite_database(&database,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),Err(_)=>true};assert!(refused,"{sql}");position=end;}assert_eq!(position,output.stdout.len());
}
