 use std::{io::Write,process::{Command,Stdio}};
 let mut expected=fixture();let bytes=export_sqlite_database(&database(&expected),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';import{Buffer}from'node:buffer';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const kinds=db.query('SELECT p.ordinal,c.attribute_kind FROM vdi3805_product p JOIN vdi3805_configuration c ON c.product_id=p.id ORDER BY p.ordinal').all();if(JSON.stringify(kinds.map(x=>x.attribute_kind))!==JSON.stringify(['valveHeating','radiator','pumpHeating','heatGenerator','generic']))throw Error('variant ownership');const fields=db.query('SELECT f.ordinal FROM vdi3805_product p JOIN vdi3805_record r ON r.product_id=p.id JOIN vdi3805_record_field f ON f.record_id=r.id ORDER BY f.ordinal').all();if(fields.length!==3||fields[2].ordinal!==2)throw Error('record ownership');const i=db.query('SELECT ordinal,product_logical_id,sheet,dn FROM vdi3805_index_entry ORDER BY ordinal').all();if(i.length!==2||i[0].sheet!==65535||i[0].dn!==65535||i[1].dn!==null)throw Error('independent index');const b=Buffer.alloc(8);b.writeDoubleBE(0.625);db.run(\"UPDATE vdi3805_valve SET kvs_m3_s=0.625,kvs_m3_s_ieee754_bits=?,kvs_m3_s_ieee754_class='finite'\",[BigInt.asIntN(64,b.readBigUInt64BE())]);db.run(\"UPDATE vdi3805_catalogue_extension SET value='Geändert 世界' WHERE map_key=''\");db.run(\"UPDATE vdi3805_curve_unit SET quantity_kind='acceleration',delta=0 WHERE axis=0\");db.run(\"UPDATE vdi3805_index_entry SET product_logical_id='another unresolved' WHERE id=1\");await Bun.write(Bun.stdout,db.serialize());db.close();";
 let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let crate::SheetAttributes::ValveHeating(a)=&mut expected.catalog.products[0].configuration.attributes else{panic!("fixture variant")};a.kvs_m3_s=0.625;expected.catalog.extensions.fields.insert(String::new(),"Geändert 世界".into());let c=expected.curves.values_mut().next().unwrap();c.x_unit.kind=crate::VdiQuantityKind::Acceleration;c.x_unit.delta=false;expected.index.entries[0].product_id="another unresolved".into();assert_eq!(Vdi3805Snapshot::from_sqlite_database(&import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap(),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
