fn vdi_duplicate_field<'a>(value:&'a mut semio_framework_dsl_record::FieldValue,path:&[serde_json::Value])->&'a mut semio_framework_dsl_record::FieldValue{
 use semio_framework_dsl_record::FieldValue as F;if path.is_empty(){return value}let step=&path[0];let next=if let Some(id)=step.get("f"){let F::Record(record)=value else{panic!("authored duplicate-map record path")};record.fields.get_mut(&(id.as_u64().unwrap()as u16)).unwrap()}else if let Some(index)=step.get("i"){let F::List(items)=value else{panic!("authored duplicate-map list path")};&mut items[index.as_u64().unwrap()as usize]}else{let F::Map(items)=value else{panic!("authored duplicate-map nested map path")};&mut items.iter_mut().find(|(key,_)|key==step["k"].as_str().unwrap()).unwrap().1};vdi_duplicate_field(next,&path[1..])
}
fn vdi_duplicate_map<'a>(record:&'a mut semio_framework_dsl_record::RecordValue,path:&[serde_json::Value])->&'a mut Vec<(String,semio_framework_dsl_record::FieldValue)>{
 let value=record.fields.get_mut(&(path[0]["f"].as_u64().unwrap()as u16)).unwrap();let semio_framework_dsl_record::FieldValue::Map(entries)=vdi_duplicate_field(value,&path[1..])else{panic!("authored duplicate-map target")};entries
}
fn vdi_duplicate_native_payload(case:&serde_json::Value,encoding:SnapshotEncoding)->store::io::IoPayload{
 use semio_framework_dsl_record::{RecordValue as R,native_encoding::{EncodedRecord,retire_field},__rt::DecodedFieldOwner};
 let source=fixture();let mut discarded:serde_json::Value=serde_json::from_str(include_str!("../../\u{1f9eb}\uFE0Ffixtures/\u{1fab6}\uFE0Fsqlite/\u{1f523}\uFE0F.json")).unwrap();let mut target=&mut discarded;for step in case["sourcePath"].as_array().unwrap(){target=if let Some(index)=step.as_u64(){&mut target[index as usize]}else{&mut target[step.as_str().unwrap()]};}target[case["key"].as_str().unwrap()]=case["entries"][0][1].clone();let discarded:Vdi3805Snapshot=serde_json::from_value(discarded).unwrap();let path=case["nativePath"].as_array().unwrap();
 store::encode_sqlite_snapshot_record_native(encoding,<Vdi3805Snapshot as store::ArtifactDsl>::envelope_id(),Vdi3805Snapshot::__dsl_spec_producer(),|native|{
  let mut root=DecodedFieldOwner::new(source.__dsl_to_record_controlled(native)?,|r:R|drop(EncodedRecord::from_record(r)));let mut old=DecodedFieldOwner::new(discarded.__dsl_to_record_controlled(native)?,|r:R|drop(EncodedRecord::from_record(r)));let count=vdi_duplicate_map(root.as_mut(),path).len();let mut entries=native.allocate_vec(count.checked_add(1).unwrap())?;let previous=std::mem::take(vdi_duplicate_map(old.as_mut(),path));let mut found=false;for(key,value)in previous{if key==case["key"].as_str().unwrap(){entries.push((key,value));found=true}else{retire_field(value)}}assert!(found);entries.append(vdi_duplicate_map(root.as_mut(),path));*vdi_duplicate_map(root.as_mut(),path)=entries;Ok(root.take())
 },&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()
}
